\label{dctrivial}
Let $\mathbf{M}=(M_j)_{j\in\mathbb{N}}\in\mathbb{R}_{>0}^{\mathbb{N}}$ be given, then \hyperlink{dc}{$(\operatorname{dc})$}, \eqref{dcMandelbrojt} and \eqref{rootaincr} are valid if
\begin{itemize}
\item[$(i)$] $\mathbf{M}$ satisfies
\begin{equation}\label{dctrivial}
0<\mathbf{M}_{\iota}\le\mathbf{M}_{\sigma}<+\infty.
\end{equation}
\item[$(ii)$] A particular case for which \eqref{dctrivial} holds is when $\mathbf{M}$ is log-convex and satisfies $\lim_{j\rightarrow+\infty}(M_j)^{\frac{1}{j}}<+\infty$.
\end{itemize}

\label{firstcharprop}
Let $\mathbf{M}=(M_j)_{j\in\mathbb{N}}\in\mathbb{R}_{>0}^{\mathbb{N}}$ be given and let $p\in[1,+\infty)$ be fixed. Consider the following assertions:
\begin{itemize}
\item[$(i)$] $\mathbf{M}$ satisfies \hyperlink{dc}{$(\operatorname{dc})$} (see \eqref{dc}); i.e.
$$\exists\;D\ge 1\;\forall\;j\in\mathbb{N}:\;\;\;M_{j+1}\le D^{j+1}M_j.$$

\item[$(ii)$] The sequence of quotients $\mu=(\mu_j)_{j\in\mathbb{N}_{>0}}$ satisfies
\begin{equation}\label{mudc}
\exists\;D\ge 1\;\forall\;j\in\mathbb{N}:\;\;\;\mu_{j+1}\le D^{j+1}.
\end{equation}

\item[$(iii)$] The sequence of quotients $\mu=(\mu_j)_{j\in\mathbb{N}_{>0}}$ satisfies
\begin{equation}\label{mudiff}
\exists\;A\ge 1\;\forall\;j\in\mathbb{N}_{>0}:\;\;\;\mu_{j+1}-\mu_j\le A^j.
\end{equation}

\item[$(iv)$] We get
\begin{equation}\label{newseriescond}
\exists\;h'>h>0:\;\;\;\sum_{j=1}^{+\infty}\left(\frac{h}{h'}\right)^{pj}(\mu_{j+1}-\mu_j)<+\infty.
\end{equation}

\item[$(v)$] $\mathbf{M}$ satisfies \eqref{rootaincr}; i.e.
$$\exists\;A\ge 1\;\forall\;j\in\mathbb{N}_{>0}:\;\;\;(M_{j+1})^{\frac{1}{j+1}}\le A(M_{j})^{\frac{1}{j}},$$
which is equivalent to
$$\forall\;d\in\mathbb{N}_{>0}\;\exists\;A\ge 1\;\forall\;j\in\mathbb{N}_{>0}:\;\;\;(M_{j+d})^{\frac{1}{j+d}}\le A(M_{j})^{\frac{1}{j}}.$$

\item[$(vi)$] $\mathbf{M}$ satisfies \eqref{dcMandelbrojt}; i.e.
$$\exists\;C\ge 1\;\forall\;j\in\mathbb{N}:\;\;\;M_j\le C^{j^2+1}.$$
\end{itemize}

Then $(v)\Rightarrow(i)\Leftrightarrow(ii)\Leftrightarrow(iii)\Rightarrow(iv)$ and $(v)\Rightarrow(vi)$ is valid. When in addition $\mathbf{M}_{\iota}>0$, then also $(i)\Rightarrow(v)$ and when $\mathbf{M}$ is log-convex, then $(i)\Rightarrow(v)$ and $(iv)\Rightarrow(iii)$. Thus for log-convex $\mathbf{M}$ the first five assertions are equivalent.

\label{mgcharrem}
Let $\mathbf{M}\in\hyperlink{LCset}{\mathcal{LC}}$. An exhaustive list of equivalent reformulations of condition \hyperlink{mg}{$(\operatorname{mg})$} for $\mathbf{M}$ is given in \cite[Thm. 3.1]{modgrowthstrange}, see also the citations there, and for the study of the mixed conditions in the weight matrix setting the following requirement was becoming relevant in \cite{modgrowthstrange}, \cite{modgrowthstrangeII}:
\begin{equation}\label{mgremequ}
\exists\;d\in\mathbb{N}_{>0}\;\exists\;B\ge 1\;\forall\;j\in\mathbb{N}_{>0}:\;\;\;\mu_j\le B(M_{dj})^{\frac{1}{dj}}.
\end{equation}
This condition is generalizing one of the equivalent reformulations: \hyperlink{mg}{$(\operatorname{mg})$} is equivalent to \eqref{mgremequ} with $d=1$ and which is stronger under the general assumption on $\mathbf{M}$ since $j\mapsto(M_j)^{\frac{1}{j}}$ is non-decreasing. It is known that \hyperlink{mg}{$(\operatorname{mg})$} is also equivalent to having the estimate in \eqref{mgremequ} with $d=1$ and $\mu_{j+1}$ instead of $\mu_j$ (see e.g. \cite[Lemma 2.2, p. 4]{whitneyextensionweightmatrix}) and one ask if also in \eqref{mgremequ} one can replace $\mu_j$ by $\mu_{j+1}$.

Indeed, this holds for any log-convex $\mathbf{M}$ satisfying \hyperlink{dc}{$(\operatorname{dc})$}: Log-convexity implies $\mu_{j+1}\ge\mu_j$ for all $j$ and so \eqref{mgremequ} follows. Conversely, by $(i)\Leftrightarrow(v)$ in Theorem \ref{firstcharprop} we can iterate \eqref{rootaincr} $d$-times and get $\mu_{j+1}\le B(M_{dj+d})^{\frac{1}{dj+d}}\le BA^d(M_{dj})^{\frac{1}{dj}}$ for all $j\in\mathbb{N}_{>0}$; thus $\mu_j$ replaced by $\mu_{j+1}$ in \eqref{mgremequ} holds with $B':=BA^d$ and note that the crucial parameter $d$ is preserved in this equivalence. Recall that there exist sequences satisfying \eqref{mgremequ} for $d\ge 2$, violating \hyperlink{mg}{$(\operatorname{mg})$} but having \hyperlink{dc}{$(\operatorname{dc})$}; see \cite[Rem. 4.5 $(ii)$, p. 23]{modgrowthstrange}: Indeed, the $q$-Gevrey sequences provide such examples.

\label{secondcharprop}
Let $\mathbf{M}=(M_j)_{j\in\mathbb{N}}\in\mathbb{R}_{>0}^{\mathbb{N}}$ be a log-convex sequence such that $\lim_{j\rightarrow+\infty}(M_j)^{\frac{1}{j}}=+\infty$ and let $p\in[1,\infty)$ be fixed. Then the following are equivalent:
\begin{itemize}
\item[$(i)$] $\mathbf{M}$ satisfies \hyperlink{dc}{$(\operatorname{dc})$} (i.e. \eqref{dc}):
$$\exists\;D\ge 1\;\forall\;j\in\mathbb{N}:\;\;\;M_{j+1}\le D^{j+1}M_j.$$

\item[$(ii)$] We get
\begin{equation}\label{newintcond}
\exists\;h'>h>0:\;\;\;\int_{0}^{+\infty}e^{p\omega_{\mathbf{M}}(ht)-p\omega_{\mathbf{M}}(h't)}dt<+\infty.
\end{equation}

\item[$(iii)$] We get
\begin{equation}\label{logabsorb}
\exists\;A\ge 1\;\exists\;B>0\;\forall\;t>0:\;\;\;\omega_{\mathbf{M}}(t)+\log(t)\le\omega_{\mathbf{M}}(At)+B.
\end{equation}
\end{itemize}

\label{thirdcharprop}
Let $\mathbf{M}=(M_j)_{j\in\mathbb{N}}\in\mathbb{R}_{>0}^{\mathbb{N}}$ be a log-convex sequence such that $\mathbf{M}_{\iota}=\lim_{j\rightarrow+\infty}(M_j)^{\frac{1}{j}}=+\infty$. Consider the following assertions:
\begin{itemize}
\item[$(i)$] $\omega_{\mathbf{M}}$ satisfies
\begin{equation}\label{thirdcharpropequ}
\liminf_{t\rightarrow+\infty}\frac{\omega_{\mathbf{M}}(t)}{(\log(t))^2}>0.
\end{equation}

\item[$(ii)$] $\omega_{\mathbf{M}}$ satisfies
\begin{equation}\label{thirdcharpropequconv}
\limsup_{t\rightarrow+\infty}\frac{\omega_{\mathbf{M}}(t)}{(\log(t))^2}<+\infty.
\end{equation}

\item[$(iii)$] $\Sigma_{\mathbf{M}}$ satisfies
$$\liminf_{t\rightarrow+\infty}\frac{\Sigma_{\mathbf{M}}(t)}{\log(t)}>0.$$

\item[$(iv)$] $\Sigma_{\mathbf{M}}$ satisfies
$$\limsup_{t\rightarrow+\infty}\frac{\Sigma_{\mathbf{M}}(t)}{\log(t)}<+\infty.$$

\item[$(v)$] $\mathbf{M}$ satisfies \hyperlink{dc}{$(\operatorname{dc})$}.
\end{itemize}
Then the equivalences $(i)\Leftrightarrow(iii)\Leftrightarrow(v)$ and $(ii)\Leftrightarrow(iv)$ hold.

\label{fourthcharprop}
Let $\mathbf{M}=(M_j)_{j\in\mathbb{N}}\in\mathbb{R}_{>0}^{\mathbb{N}}$ be a log-convex sequence such that $\mathbf{M}_{\iota}=\lim_{j\rightarrow+\infty}(M_j)^{\frac{1}{j}}=+\infty$. Then the following are equivalent:
\begin{itemize}
\item[$(i)$] $\mathbf{M}$ satisfies \eqref{dcMandelbrojt}.

\item[$(ii)$] $\omega_{\mathbf{M}}$ satisfies \eqref{thirdcharpropequ}.
\end{itemize}

\label{spacedc}
Let $\mathbf{M}=(M_j)_{j\in\mathbb{N}}\in\mathbb{R}_{>0}^{\mathbb{N}}$ be a log-convex sequence such that $\mathbf{M}_{\iota}=\lim_{j\rightarrow+\infty}(M_j)^{\frac{1}{j}}=+\infty$. Then the following are equivalent:
\begin{itemize}
\item[$(i)$] The spaces $\mathcal{E}_{\{\mathbf{M}\}}$ (Roumieu-type) and/or $\mathcal{E}_{(\mathbf{M})}$ are/is derivation closed.

\item[$(ii)$] $\mathbf{M}$ satisfies \eqref{dc}.
\end{itemize}

\label{nqadef}
A sequence $\mathbf{M}=(M_j)_{j\in\mathbb{N}}\in\mathbb{R}_{>0}^{\mathbb{N}}$ such that $j\mapsto(M_j)^{\frac{1}{j}}$ is non-decreasing is called \emph{non-quasianalytic} if
\begin{equation}\label{nqadefequ}
\sum_{j\in\mathbb{N}_{>0}}\frac{1}{(M_j)^{\frac{1}{j}}}<+\infty.
\end{equation}
If this series is divergent, then $\mathbf{M}$ is called \emph{quasianalytic.}

\label{Mcounterexample}
There exist sequences $\mathbf{M}\in\mathbb{R}_{>0}^{\mathbb{N}}$ satisfying the following properties:
\begin{itemize}
\item[$(a)$] $\mathbf{M}$ is normalized (i.e. $1=M_0\le M_1$), $j\mapsto(M_j)^{\frac{1}{j}}$ is non-decreasing and $\mathbf{M}_{\iota}=\lim_{j\rightarrow+\infty}(M_j)^{\frac{1}{j}}=+\infty$, but $\mathbf{M}$ is not log-convex (and hence, in particular, $\mathbf{M}\notin\hyperlink{LCset}{\mathcal{LC}}$).

\item[$(b)$] $\mathbf{M}$ does not satisfy derivation closedness, i.e. \eqref{dc} fails, hence assertions $(i)-(iii)$ and $(v)$ in Theorem \ref{firstcharprop} fail too and so, in particular, \eqref{rootaincr} is also violated.

\item[$(c)$] \eqref{dcMandelbrojt} is valid, indeed even
\begin{equation}\label{dcMandelbrojtviol1}
\lim_{j\rightarrow+\infty}\frac{\log(M_j)}{j^2}=0\Leftrightarrow\lim_{j\rightarrow+\infty}\frac{\log((M_j)^{\frac{1}{j}})}{j}=0.
\end{equation}

\item[$(d)$] $(a)-(c)$ are not depending on the notion of \emph{(non-)quasianalyticity;} i.e. there exist both non-quasianalytic and quasianalytic $\mathbf{M}$ satisfying $(a)-(c)$.

\item[$(e)$] Any sequence $\mathbf{N}\in\mathbb{R}_{>0}^{\mathbb{N}}$ being equivalent to $\mathbf{M}$ satisfies $\lim_{j\rightarrow+\infty}(N_j)^{\frac{1}{j}}=+\infty$, $(b)$, $(c)$, \eqref{nqadefequ} if and only if $\mathbf{M}$ does so (cf. $(d)$). Finally, $\mathbf{N}$ cannot be log-convex and hence the whole equivalence class does not contain any log-convex weight sequence.
\end{itemize}
